        self.pos += 1
        return tok

    def error(self, message: str) -> SQLSyntaxError:
        tok = self.peek()
        shown = tok.value if tok.type is not TokenType.EOF else "end of input"
        return SQLSyntaxError(f"{message} near {shown!r}")

    def at_kw(self, word: str) -> bool:
        tok = self.peek()
        return tok.type is TokenType.KEYWORD and tok.value == word

    def at_op(self, symbol: str) -> bool:
        tok = self.peek()
        return tok.type is TokenType.OPERATOR and tok.value == symbol

    def at_eof(self) -> bool:
        return self.peek().type is TokenType.EOF

    def expect_kw(self, word: str) -> None:
        if not self.at_kw(word):
            raise self.error(f"expected {word}")
        self.pos += 1

    def expect_op(self, symbol: str) -> None:
        if not self.at_op(symbol):
            raise self.error(f"expected {symbol!r}")
        self.pos += 1

    def ident(self) -> str:
        tok = self.peek()
        if tok.type is not TokenType.IDENTIFIER:
            raise self.error("expected identifier")
        self.pos += 1
        return tok.value

    def ident_list(self) -> tuple[str, ...]:
        names = [self.ident()]
        while self.at_op(","):
            self.pos += 1
            names.append(self.ident())
        return tuple(names)

    # -- statements ------------------------------------------------------

    def statement(self) -> Statement:
        tok = self.peek()
        if tok.type is TokenType.KEYWORD:
            if tok.value == "CREATE":
                return self.create()
            if tok.value == "DROP":
                return self.drop()
            if tok.value == "INSERT":
                return self.insert()
            if tok.value == "SELECT":
                return self.select()
            if tok.value == "DELETE":
                return self.delete()
        raise self.error("expected a statement")

    def create(self) -> CreateTableStmt:
        self.expect_kw("CREATE")
        self.expect_kw("TABLE")
        table = self.ident()
        self.expect_op("(")
        columns = [self.column_def()]
        while self.at_op(","):
            self.pos += 1
            columns.append(self.column_def())
        self.expect_op(")")
        return CreateTableStmt(table, tuple(columns))

    def column_def(self) -> ColumnDef:
        name = self.ident()
        tok = self.peek()
        if tok.type is TokenType.KEYWORD and tok.value in ColumnType.__members__:
            self.pos += 1
            return ColumnDef(name, ColumnType[tok.value])
        raise self.error("expected column type")

    def drop(self) -> DropTableStmt:
        self.expect_kw("DROP")
        self.expect_kw("TABLE")
        return DropTableStmt(self.ident())

    def insert(self) -> InsertStmt:
        self.expect_kw("INSERT")
        self.expect_kw("INTO")
        table = self.ident()
        columns = None
        if self.at_op("("):
            self.pos += 1
            columns = self.ident_list()
            self.expect_op(")")
        self.expect_kw("VALUES")
        self.expect_op("(")
        values = [self.literal()]
        while self.at_op(","):
            self.pos += 1
            values.append(self.literal())
        self.expect_op(")")
        return InsertStmt(table, columns, tuple(values))

    def literal(self) -> Value:
        tok = self.peek()
        if tok.type is TokenType.INTEGER:
            self.pos += 1
            return int(tok.value)
        if tok.type is TokenType.STRING:
            self.pos += 1
            return tok.value
        if tok.type is TokenType.KEYWORD and tok.value in ("TRUE", "FALSE", "NULL"):
            self.pos += 1
            return {"TRUE": True, "FALSE": False, "NULL": None}[tok.value]
        raise self.error("expected literal")

    def select(self) -> SelectStmt:
        self.expect_kw("SELECT")
        if self.at_op("*"):
            self.pos += 1
            columns = None
        else:
            columns = self.ident_list()
        self.expect_kw("FROM")
        table = self.ident()
        return SelectStmt(table, columns, self.opt_where())

    def delete(self) -> DeleteStmt:
        self.expect_kw("DELETE")
        self.expect_kw("FROM")
        table = self.ident()
        return DeleteStmt(table, self.opt_where())

    def opt_where(self) -> Expr | None:
        if self.at_kw("WHERE"):
            self.pos += 1
            return self.expr()
        return None

    # -- expressions -----------------------------------------------------

    def expr(self) -> Expr:
        left = self.and_expr()
        while self.at_kw("OR"):
            self.pos += 1
            left = Or(left, self.and_expr())
        return left

    def and_expr(self) -> Expr:
        left = self.not_expr()
        while self.at_kw("AND"):
            self.pos += 1
            left = And(left, self.not_expr())
        return left

    def not_expr(self) -> Expr:
        if self.at_kw("NOT"):
            self.pos += 1
            return Not(self.not_expr())
        return self.predicate()

    def predicate(self) -> Expr:
        left = self.primary()
        tok = self.peek()
        if tok.type is TokenType.OPERATOR and tok.value in COMPARISON_OPS:
            self.pos += 1
            return Comparison(tok.value, left, self.primary())
        if self.at_kw("IS"):
            self.pos += 1
            negated = False
            if self.at_kw("NOT"):
                self.pos += 1
                negated = True
            self.expect_kw("NULL")
            return IsNull(left, negated)
        return left

    def primary(self) -> Expr:
        tok = self.peek()
        if tok.type is TokenType.IDENTIFIER:
            self.pos += 1
            return ColumnRef(tok.value)
        if self.at_op("("):
            self.pos += 1
            inner = self.expr()
            self.expect_op(")")
            return inner
        return Literal(self.literal())


def parse(tokens: list[Token]) -> Statement:
    """Parse exactly one statement, optionally followed by a single ';',
    then EOF.

    Raises:
        SQLSyntaxError: if the tokens are not exactly one valid statement
            (including empty input, a lone ';', or trailing tokens).
    """
    parser = _Parser(tokens)
    stmt = parser.statement()
    if parser.at_op(";"):
        parser.pos += 1
    if not parser.at_eof():
        raise parser.error("unexpected token")
    return stmt


def parse_script(tokens: list[Token]) -> list[Statement]:
    """Parse zero or more ';'-separated statements up to EOF.

    Empty statements (consecutive ';' or a trailing ';') are skipped; an
    empty token stream (just EOF) yields ``[]``.

    Raises:
        SQLSyntaxError: if any statement is malformed.
    """
    parser = _Parser(tokens)
    stmts: list[Statement] = []
    while True:
        while parser.at_op(";"):
            parser.pos += 1
        if parser.at_eof():
            return stmts
        stmts.append(parser.statement())
        if not parser.at_op(";") and not parser.at_eof():
            raise parser.error("unexpected token")


def parse_expression(tokens: list[Token]) -> Expr:
    """Parse a single WHERE-style expression that must consume every token
    up to EOF.

    Raises:
        SQLSyntaxError: if the tokens do not form exactly one expression.
    """
    parser = _Parser(tokens)
    expr = parser.expr()
    if not parser.at_eof():
        raise parser.error("unexpected token")
    return expr
